// AI service (Ryzom: ai_service). Owns every defender's hit points, death
// and respawn, and the zone objective.
//
// One deliberate difference from Ryzom: the shard has no copy of the
// battlefield geometry (it is generated by the client's renderer), so it
// cannot trace line of sight itself. Movement and shooting decisions run in
// one client per zone — the "simulation owner" — which streams the defenders'
// state up; the shard rebroadcasts it, decides who owns the zone, hands the
// zone over when the owner leaves, and stays the single authority on damage,
// death, XP and respawn.
import { npcHp, npcDamageMul, NPC_RESPAWN, ZONE_RESET_AFTER_CAPTURE, HIT_CAP, WEAPON_SKILL, isUnlocked, weaponMods } from '../rules.mjs';

const finite = v => typeof v === 'number' && Number.isFinite(v);
const vec3 = a => Array.isArray(a) && a.length === 3 && a.every(finite);
const r2 = v => Math.round(v * 100) / 100;
const RANGE = { smg: 125, lmg: 175, pistol: 115, sniper: 235, nade: 14 };

export function installAI(ctx){
  for (const z of ctx.zones){
    const [lo, hi] = z.def.level;
    z.npcs = [];
    for (let i = 0; i < z.def.npcs; i++){
      const lvl = lo + Math.floor((i * 7919) % z.def.npcs * (hi - lo + 1) / z.def.npcs);
      z.npcs.push({ i, lvl, hpMax: npcHp(lvl), hp: npcHp(lvl), alive: true, known: false,
                    x: 0, y: 0, z: 0, yaw: 0, st: 0, fl: 0, respawnAt: 0, dmg: new Map(), gen: 0 });
    }
    z.authority = 0;
    z.objective = { state: 'locked', until: 0, by: '' };
  }

  const npcList = z => z.npcs.map(n => ({ i: n.i, lvl: n.lvl, hp: n.hp, hpMax: n.hpMax, alive: n.alive, known: n.known,
                                         x: r2(n.x), y: r2(n.y), z: r2(n.z), yaw: r2(n.yaw), st: n.st, gen: n.gen }));

  function setAuthority(z, pid){
    if (z.authority === pid) return;
    const old = ctx.players.get(z.authority);
    if (old && old.zone === z.idx) ctx.send(old, { t: 'authority', on: false });
    z.authority = pid || 0;
    const p = ctx.players.get(z.authority);
    if (p) ctx.send(p, { t: 'authority', on: true, npcs: npcList(z) });
    ctx.zoneSend(z, { t: 'owner', pid: z.authority });
  }

  ctx.bus.on('zoneEnter', ({ p, z, msg }) => {
    msg.npcs = npcList(z);
    msg.objective = { state: z.objective.state, by: z.objective.by, left: z.npcs.filter(n => n.alive).length };
    msg.dmgMul = z.npcs.map(n => r2(npcDamageMul(n.lvl)));
    if (!ctx.players.get(z.authority) || ctx.players.get(z.authority).zone !== z.idx){ z.authority = 0; }
    msg.authority = !z.authority;
    msg.owner = z.authority || p.pid;
    if (!z.authority) z.authority = p.pid;
  });
  /* hand the zone to whoever has been in it longest */
  function handOver(z){
    let next = 0, since = Infinity;
    for (const pid of z.players){ const q = ctx.players.get(pid); if (q && q.zoneAt < since){ since = q.zoneAt; next = pid; } }
    z.authority = 0;
    setAuthority(z, next);
  }
  ctx.bus.on('zoneLeave', ({ p, z }) => { if (z.authority === p.pid) handOver(z); });

  /* ---- the owner's stream ---- */
  ctx.bus.on('c:npcState', ({ p, m }) => {
    if (p.zone < 0) return;
    const z = ctx.zones[p.zone];
    if (z.authority !== p.pid || !Array.isArray(m.l)) return;
    for (const e of m.l){
      if (!Array.isArray(e) || e.length < 7) continue;
      const n = z.npcs[e[0] | 0];
      if (!n || !n.alive || (e[7] | 0) !== n.gen) continue;
      if (![e[1], e[2], e[3], e[4]].every(finite)) continue;
      n.x = Math.max(-31, Math.min(31, e[1])); n.y = e[2]; n.z = Math.max(-31, Math.min(31, e[3]));
      n.yaw = e[4]; n.st = e[5] | 0; n.fl = e[6] | 0; n.known = true;
    }
  });
  ctx.bus.on('c:npcFire', ({ p, m }) => {
    if (p.zone < 0) return;
    const z = ctx.zones[p.zone], n = z.npcs[m.i | 0];
    if (z.authority !== p.pid || !n || !n.alive || !vec3(m.from) || !vec3(m.to)) return;
    const tgt = m.tgt | 0, dmg = finite(m.dmg) ? Math.max(0, Math.min(16, m.dmg)) * npcDamageMul(n.lvl) : 0;
    const out = { t: 'npcFire', i: n.i, from: m.from.map(r2), to: m.to.map(r2), r: m.r ? 1 : 0 };
    for (const pid of z.players){
      if (pid === p.pid) continue;
      const q = ctx.players.get(pid);
      if (q) ctx.send(q, pid === tgt ? { ...out, dmg: r2(dmg) } : out);
    }
  });
  ctx.bus.on('c:npcNade', ({ p, m }) => {
    if (p.zone < 0) return;
    const z = ctx.zones[p.zone], n = z.npcs[m.i | 0];
    if (z.authority !== p.pid || !n || !n.alive || !vec3(m.from) || !vec3(m.vel)) return;
    ctx.zoneSend(z, { t: 'npcNade', i: n.i, from: m.from.map(r2), vel: m.vel.map(r2), lvl: n.lvl }, p.pid);
  });
  /* the owner relays the squad's alarm calls so everyone reads the radio */
  ctx.bus.on('c:npcSay', ({ p, m }) => {
    if (p.zone < 0) return;
    const z = ctx.zones[p.zone];
    if (z.authority !== p.pid || typeof m.fr !== 'string') return;
    ctx.zoneSend(z, { t: 'npcSay', i: m.i | 0, fr: m.fr.slice(0, 80), vi: String(m.vi || '').slice(0, 80) }, p.pid);
  });

  /* ---- damage: claimed by the shooter, judged here ---- */
  ctx.bus.on('c:hit', ({ p, m }) => {
    if (p.zone < 0 || p.dead) return;
    const z = ctx.zones[p.zone], n = z.npcs[m.i | 0];
    if (!n || !n.alive || (m.gen | 0) !== n.gen) return;
    const sk = m.w === 'nade' ? 'nade' : WEAPON_SKILL[m.w | 0];
    if (!sk || !isUnlocked(p.char.skills, sk)) return;
    const cap = HIT_CAP[sk];
    /* rate: a weapon cannot land more hits per second than it fires */
    const now = ctx.now();
    const win = (p.hitWin || (p.hitWin = {}))[sk] || (p.hitWin[sk] = { t: now, n: 0 });
    if (now - win.t > 1){ win.t = now; win.n = 0; }
    if (++win.n > cap.rate) return;
    if (n.known && Math.hypot(p.x - n.x, p.z - n.z) > RANGE[sk] + 6) return;
    const raw = finite(m.dmg) ? Math.max(0, Math.min(cap.dmg, m.dmg)) : 0;
    const dmg = raw * weaponMods(p.char.skills[sk].lv).damage;
    if (dmg <= 0) return;
    const gk = p.team ? 't' + p.team.id : 'p' + p.pid;
    const g = n.dmg.get(gk) || { dmg: 0, team: p.team, pid: p.pid, used: new Map() };
    g.dmg += Math.min(dmg, n.hp); g.used.set(p.pid, sk);
    n.dmg.set(gk, g);
    if (sk !== 'nade') p.char.lastSkill = sk;
    n.hp -= dmg;
    if (n.hp > 0){ ctx.zoneSend(z, { t: 'npcHp', i: n.i, hp: r2(n.hp), by: p.pid, head: m.head ? 1 : 0 }); return; }
    n.hp = 0; n.alive = false;
    n.respawnAt = now + NPC_RESPAWN[0] + ctx.rnd() * (NPC_RESPAWN[1] - NPC_RESPAWN[0]);
    ctx.zoneSend(z, { t: 'npcDie', i: n.i, by: p.pid, head: m.head ? 1 : 0, blast: sk === 'nade' ? 1 : 0, name: p.name });
    ctx.bus.emit('npcKilled', { z, npc: n, killer: p, head: !!m.head, weapon: sk });
    n.dmg = new Map();
    const left = z.npcs.filter(q => q.alive).length;
    if (left === 0 && z.objective.state === 'locked'){
      z.objective = { state: 'open', until: now + 150, by: '' };
      ctx.zoneSend(z, { t: 'objective', state: 'open', left: 0 });
    } else ctx.zoneSend(z, { t: 'objective', state: z.objective.state, left });
  });

  /* ---- the flag / the satchel ---- */
  ctx.bus.on('c:plant', ({ p }) => {
    if (p.zone < 0 || p.dead) return;
    const z = ctx.zones[p.zone], o = z.def.objective;
    if (z.objective.state !== 'open') return;
    if (Math.hypot(p.x - o.x, p.z - o.z) > 3.4) return;
    z.objective = { state: 'captured', until: ctx.now() + ZONE_RESET_AFTER_CAPTURE, by: p.name };
    p.char.stats.captures++; p.dirty = true;
    ctx.zoneSend(z, { t: 'objective', state: 'captured', by: p.name, pid: p.pid, reset: ZONE_RESET_AFTER_CAPTURE });
    ctx.bus.emit('captured', { z, p });
  });

  function respawn(z, n){
    n.alive = true; n.hp = n.hpMax; n.gen++; n.known = false; n.dmg = new Map(); n.st = 0;
    ctx.zoneSend(z, { t: 'npcSpawn', i: n.i, hp: n.hp, hpMax: n.hpMax, gen: n.gen });
  }

  ctx.bus.on('tick', tk => {
    if (tk % 5) return;
    const now = ctx.now();
    for (const z of ctx.zones){
      const o = z.objective;
      if (o.state === 'captured' && now >= o.until){
        /* the counter-attack: the whole garrison comes back at once */
        for (const n of z.npcs) if (!n.alive) respawn(z, n);
        z.objective = { state: 'locked', until: 0, by: '' };
        ctx.zoneSend(z, { t: 'objective', state: 'locked', left: z.npcs.length, reset: true });
        continue;
      }
      if (o.state === 'open'){
        if (now < o.until) continue;              // hold the hill while someone runs for the flag
        z.objective = { state: 'locked', until: 0, by: '' };
      }
      let back = false;
      for (const n of z.npcs) if (!n.alive && now >= n.respawnAt){ respawn(z, n); back = true; }
      if (back) ctx.zoneSend(z, { t: 'objective', state: 'locked', left: z.npcs.filter(q => q.alive).length });
      /* an owner that fell silent loses the zone */
      const a = ctx.players.get(z.authority);
      if (z.authority && (!a || a.zone !== z.idx)) handOver(z);
    }
  });
}
